import { createDialogModal, type DialogModal } from "@cssints/headless";
import { Portal } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { frame } from "cssints/frame" with { type: "cssints" };
import { surface } from "cssints/surface" with { type: "cssints" };
import {
  createContext,
  createEffect,
  createUniqueId,
  merge,
  omit,
  Show,
  untrack,
  useContext,
} from "solid-js";

import { Button } from "./button.tsx";
import { createOverlayMotion, type OverlayMotion } from "./overlay-motion.ts";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface DialogProps {
  /** The dialog's accessible name: `role="dialog"` needs one. */
  readonly label: string;
  /** The description under the panel's first row. An `alert` should have one (APG). */
  readonly description?: string;
  /** Controlled: the host owns the open state. */
  readonly open?: boolean;
  readonly defaultOpen?: boolean;
  readonly onOpenChange?: (open: boolean) => void;
  /** `role="alertdialog"`: an interrupting message, whose description is read out with its name. */
  readonly alert?: boolean;
  /** `aria-modal` (default `true`): the rest of the page is inert while it is open. */
  readonly modal?: boolean;
  /** A click on the backdrop closes it (default `true`). */
  readonly dismissable?: boolean;
  /** Escape cannot close it. */
  readonly keyboardDismissDisabled?: boolean;
  /**
   * The panel enters and leaves on `@cssints/machine` (`closed`, `entering`, `open`, `leaving`) and the layer is
   * unmounted only at `closed`. The primitive still owns the open state and the whole APG contract; read once.
   */
  readonly animated?: boolean;
  /** The motion preference; left out, `prefers-reduced-motion: reduce` is read once. */
  readonly reducedMotion?: boolean;
  /** Every animation the layer starts, once, after `animate()`: a test pauses it and steps the timeline. */
  readonly onAnimate?: (animation: Animation) => void;
  /** The element the layer is portalled into (default `document.body`), for a host that has its own modal root. */
  readonly mount?: Element;
  readonly id?: string;
  readonly children?: JSX.Element;
}

export type DialogTriggerPartProps = PartProps;

export interface DialogTriggerProps extends Renderable<DialogTriggerPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DialogContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DialogTitleProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface DialogCloseProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

const DialogContext = createContext<{
  readonly dialog: DialogModal;
  readonly descriptionId: string;
  readonly label: () => string;
  readonly description: () => string | undefined;
  readonly mount: () => Element | undefined;
  readonly animated: boolean;
  readonly motion: OverlayMotion;
}>();

// The layer holds the page still and takes the wash; the backdrop sits in it and takes the dismiss click; the panel floats
// above both (a positioned box paints over a plain one), is a surface and a frame like a card, and scrolls inside itself so a
// long dialog never grows past the viewport. An animated layer that is on its way out takes no clicks: the box is painted
// until it lands, but the dialog is already closed, so a reader's click belongs to the page under it.
const layerClass = css.cn(
  css.position("fixed"),
  css.inset("0"),
  // `z-index` takes an `<integer>`, which a `number` token is not: the custom property is the knob
  css.zIndex("var(--z-dialog)"),
  css.display("grid"),
  css.placeItems("center"),
  css.padding(t.space._4),
  css.overflow("auto"),
  css.attr("data-state", "leaving")(css.pointerEvents("none")),
);

const backdropClass = css.cn(css.position("absolute"), css.inset("0"), css.bg(t.color.scrim));

const panelClass = css.cn(
  frame().radius(t.radius.xl).padding(t.space._4).border("1px"),
  surface().color(t.color.overlayBackground),
  css.borderColor(t.color.overlayBorder),
  css.color(t.color.text),
  css.boxShadow(t.shadow.popover),
  css.position("relative"),
  css.display("flex"),
  css.flexDirection("column"),
  css.gap(t.space._3),
  css.width("min(28rem, 100%)"),
  css.maxHeight("calc(100dvh - 2 * 16px)"),
  css.overflow("auto"),
  // the panel takes focus itself (`tabindex="-1"`): a ring around the whole dialog is noise, the control inside has it
  css.outline("none"),
);

const titleClass = css.cn(
  css.margin("0"),
  css.fontSize(t.font.sizeLg),
  css.fontWeight("600"),
  css.color(t.color.text),
);

const descriptionClass = css.cn(
  css.margin("0"),
  css.fontSize(t.font.size),
  css.color(t.color.muted),
);

// The panel's track: a fade with a small lift, so the layer reads as leaving rather than as a cut. The resting look is
// the track's open end in both directions (the animation is cancelled in the same task that writes the next state).
const dialogFrame = (fraction: number): Keyframe => ({
  opacity: fraction,
  transform: `scale(${0.96 + 0.04 * fraction}) translateY(${(1 - fraction) * 8}px)`,
});

/**
 * APG modal dialog, styled: `Dialog.Trigger` opens it, `Dialog.Content` is the panel, and the backdrop closes it unless the
 * host says otherwise. `createDialogModal` owns the open state (controlled by `open`), the ARIA and the Escape; the kit adds
 * the scrim, the surface, focus into the panel and back to whatever opened it, and the page's scroll lock.
 */
export const Dialog = (props: DialogProps): JSX.Element => {
  // the description's id is the dialog's `aria-describedby`, and its paragraph is always in the panel: `alert` needs a
  // description (APG), and a reference to a missing id is worse than an empty one
  const descriptionId = createUniqueId();
  const dialog = createDialogModal({
    get value() {
      return props.open;
    },
    defaultOpen: props.defaultOpen,
    get modal() {
      return props.modal;
    },
    role: props.alert === true ? "alertdialog" : "dialog",
    describedby: descriptionId,
    id: props.id,
    get dismissable() {
      return props.dismissable;
    },
    get keyboardDismissDisabled() {
      return props.keyboardDismissDisabled;
    },
    get onOpenChange() {
      return props.onOpenChange;
    },
  });
  // the visual lifecycle, on the primitive's open state: the machine starts where the primitive is, so a dialog that is
  // open at mount is painted open rather than entered
  const animated = untrack(() => props.animated) === true;
  const motion = createOverlayMotion({
    animated,
    open: () => dialog.open(),
    frame: dialogFrame,
    get reducedMotion() {
      return props.reducedMotion;
    },
    get onAnimate() {
      return props.onAnimate;
    },
  });
  // the panel names itself with `aria-label`: the label is a prop, and a title part is the visible heading, not the name
  const label = () => props.label;
  const description = () => props.description;
  const mount = () => props.mount;
  return (
    <DialogContext value={{ dialog, descriptionId, label, description, mount, animated, motion }}>
      {props.children}
    </DialogContext>
  );
};

/** The button that opens the dialog: `Button` unless `render` says otherwise. */
export const DialogTrigger = (props: DialogTriggerProps): JSX.Element => {
  const { dialog } = useContext(DialogContext);
  const rest = omit(props, "render", "class", "children");
  // no `data-part` of its own: the part renders a `Button` by default, and the button owns the attribute, as a `Field`'s
  // control renders an `Input`. The trigger is the element with `aria-haspopup="dialog"`.
  const merged = merge(rest, dialog.triggerProps, () => ({
    get class() {
      return css.cn(props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/**
 * The panel and the wash under it. Nothing is in the DOM while the dialog is closed; focus moves into the panel when it
 * opens and back to whatever had it when it closes, and the page does not scroll while it is open. The layer is portalled
 * into `document.body` (or `Dialog`'s `mount`) so an ancestor's `transform`, `filter`, `contain` or `overflow` can neither
 * clip it nor become the containing block of its `position: fixed`.
 *
 * With `animated` the layer stays mounted through `leaving` and is removed at `closed`; the panel keeps no `hidden`
 * attribute while it leaves (a panel cut from the page mid-slide is the frame `Atomic` rules out) and its `data-state` is
 * the box's phase. Without it, nothing below the primitive changes.
 */
export const DialogContent = (props: DialogContentProps): JSX.Element => {
  const { dialog, descriptionId, label, description, mount, animated, motion } =
    useContext(DialogContext);
  let panel: HTMLDivElement | undefined;
  let restore: HTMLElement | null = null;
  let scroll: string | undefined;
  createEffect(
    () => dialog.open(),
    (open) => {
      if (open) {
        restore = document.activeElement instanceof HTMLElement ? document.activeElement : null;
        scroll = document.body.style.overflow;
        document.body.style.overflow = "hidden";
        panel?.focus();
      } else {
        if (scroll !== undefined) {
          document.body.style.overflow = scroll;
          scroll = undefined;
        }
        restore?.focus();
        restore = null;
      }
    },
  );
  return (
    <Show when={(animated && motion.visible()) || dialog.open()}>
      <Portal mount={mount()}>
        <div
          data-part="dialog-layer"
          // the box's phase, for the layer's own rule: a leaving layer takes no clicks
          data-state={animated ? motion.phase() : undefined}
          class={layerClass}
        >
          <div {...dialog.backdropProps} data-part="dialog-backdrop" class={backdropClass} />
          {renderPart(
            props,
            merge(omit(props, "render", "class", "children"), dialog.dialogProps, () => ({
              "aria-label": label(),
              "data-part": "dialog",
              // the box's phase, for the CSS and the tests; the layer's presence is the same store's other field
              get "data-state"() {
                return animated ? motion.phase() : undefined;
              },
              // the primitive's `hidden` is `!open()`, which is exactly the frame a leaving panel must not be cut from
              get hidden() {
                return animated ? false : !dialog.open();
              },
              get class() {
                return css.cn(panelClass, props.class);
              },
            })),
            undefined,
            (part) => (
              <div
                {...part}
                ref={(element: HTMLDivElement) => {
                  panel = element;
                  motion.attach(element);
                }}
              >
                <p
                  id={descriptionId}
                  data-part="dialog-description"
                  class={descriptionClass}
                  hidden={description() === undefined}
                >
                  {description()}
                </p>
                {props.children}
              </div>
            ),
          )}
        </div>
      </Portal>
    </Show>
  );
};

/** The visible heading of the panel. */
export const DialogTitle = (props: DialogTitleProps): JSX.Element =>
  renderPart(
    props,
    {
      "data-part": "dialog-title",
      get class() {
        return css.cn(titleClass, props.class);
      },
    },
    undefined,
    (part) => <h2 {...part}>{props.children}</h2>,
  );

/** A button that closes the dialog, inside the panel. */
export const DialogClose = (props: DialogCloseProps): JSX.Element => {
  const { dialog } = useContext(DialogContext);
  const merged = merge(omit(props, "render", "class", "children"), dialog.dismissProps, () => ({
    get class() {
      return css.cn(props.class);
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button tone="quiet" {...part}>
      {props.children}
    </Button>
  ));
};

// The machine of an animated modal layer: the box of `specs/patterns/animation.qnt` (closed, entering, open, leaving),
// and nothing of the modal contract. The APG half — focus in and back to the invoker, the Tab cycle, Escape, the
// backdrop, `aria-modal`, the scroll lock — is `specs/apg/dialog-modal.qnt` and stays in `@cssints/headless`
// (`createDialogModal`, `createDrawer`). A `Dialog` or a `Drawer` with `animated` is the two questions together: the
// primitive decides *whether* the layer is open, this machine decides *how* it leaves and enters, and the layer is
// unmounted only at `closed`.
//
// The intents are the primitive's, not the DOM's. The machine follows `open()`: a request a controlled host refuses
// never moves the box (no slide out and back), and the box starts closing only once the open state really changed. That
// is the one place this host differs from the disclosure's, which starts the animation from an intent. Two `close`
// intents in one frame are one dismissal because the machine has no `close` transition while `leaving` — a superseded
// intent, not a debounce — and because `createControllable` asks the host once for an intent it is still waiting on.
//
// Leaving a state cancels the effect the machine issued, and a cancelled animation's own late completion carries the
// dead handle's id, which the machine drops before it looks at a transition (`CancelledFinishIgnored`,
// `StaleCarriesCancelled`). A reversal keeps the box where it is: the host reads the running animation's `currentTime`
// before it cancels it, so the replacement starts at that fraction (`ReversalKeepsPosition`). With
// `prefers-reduced-motion: reduce` an intent lands in one step and no transition is entered (`ReducedMotionSkips`).
import {
  type ConfigEvent,
  createMachine,
  defineMachine,
  type EffectHandle,
  type Machine,
  type Transition,
  type TransitionList,
} from "@cssints/machine";
import { type MachineStore, createMachineStore } from "@cssints/machine/solid";
import { type Accessor, createEffect, onCleanup, untrack } from "solid-js";

/** How long a full open or close takes: the drawer's slide and the dialog's fade are one track. */
export const OVERLAY_MOTION_DURATION = 200;

/** The box: the four states `specs/patterns/animation.qnt` calls `visual`. */
export type OverlayMotionPhase = "closed" | "entering" | "open" | "leaving";

/** The machine's context: the accepted intent, what the box has settled at, and the motion preference. */
export interface OverlayMotionContext {
  /** The primitive's open state (`dialog.open()`): what `aria-expanded` and `aria-modal` say. */
  readonly logical: boolean;
  /** What the box has settled at; only an effect's completion moves it. */
  readonly committed: "closed" | "open";
  /** `prefers-reduced-motion: reduce` (or the `reducedMotion` override): no transition is entered. */
  readonly reduced: boolean;
}

// a type alias, not an interface: `PayloadMap` is an index signature, and only an alias is assignable to one
type OverlayMotionPayloads = {
  readonly open: undefined;
  readonly close: undefined;
  readonly finish: { readonly id: number };
  readonly motion: { readonly reduced: boolean };
};

/** The machine's events: the protocol's own, not the DOM's. */
export type OverlayMotionEvent =
  | { readonly type: "open" }
  | { readonly type: "close" }
  | { readonly type: "finish"; readonly id: number }
  | { readonly type: "motion"; readonly reduced: boolean };

/** The running machine, as the components and their tests name it. */
export type OverlayMotionMachine = Machine<
  OverlayMotionContext,
  OverlayMotionPhase,
  OverlayMotionEvent
>;

type OverlayMotionConfig = ConfigEvent<OverlayMotionPayloads>;

// A same-direction intent has no transition at all: the machine drops it, so the running effect is neither cancelled
// nor restarted. Reduced motion is the same list's first entry: the box lands at the intent in one step, no effect.
const toward = (open: boolean): TransitionList<OverlayMotionContext, OverlayMotionConfig> => [
  {
    guard: (context) => context.reduced,
    target: open ? "open" : "closed",
    assign: { logical: open, committed: open ? "open" : "closed" },
  },
  {
    target: open ? "entering" : "leaving",
    assign: { logical: open },
    effect: { type: "animate", to: open ? "open" : "closed" },
  },
];

// The preference moves while the box is still: keep the phase, nothing else changes.
const followMotion = (
  phase: OverlayMotionPhase,
): Transition<OverlayMotionContext, OverlayMotionConfig> => ({
  target: phase,
  assign: (context, event) => ({
    reduced: event.type === "motion" ? event.reduced : context.reduced,
  }),
});

// The preference turns on mid-flight: the effect is cancelled by leaving the state, the box lands at the intent.
const stopMotion = (
  target: "open" | "closed",
): Transition<OverlayMotionContext, OverlayMotionConfig> => ({
  target,
  guard: (_context, event) => event.type === "motion" && event.reduced,
  assign: { reduced: true, committed: target },
});

const settle = (target: "open" | "closed"): Transition<OverlayMotionContext, OverlayMotionConfig> => ({
  target,
  assign: { committed: target },
});

/**
 * The protocol as data, for the components and for a harness: four states, four events, and no `close` in `leaving`
 * (a second dismissal is a superseded intent) and no `open` in `open` (a repeated open is none). `start` follows the
 * primitive, so a dialog that is open at mount is painted open rather than entered.
 */
export const overlayMotionDefinition = (
  reduced: boolean,
  start: "open" | "closed" = "closed",
) =>
  defineMachine<OverlayMotionPayloads>()({
    start,
    initial: { logical: start === "open", committed: start, reduced },
    states: {
      closed: {
        on: { open: toward(true), motion: followMotion("closed") },
      },
      entering: {
        on: { close: toward(false), finish: settle("open"), motion: stopMotion("open") },
      },
      open: {
        on: { close: toward(false), motion: followMotion("open") },
      },
      leaving: {
        on: { open: toward(true), finish: settle("closed"), motion: stopMotion("closed") },
      },
    },
  });

/** A frame of the panel on the box's track: 0 is closed, 1 is open. */
export type OverlayFrame = (fraction: number) => Keyframe;

/** What the host needs: the primitive's open state, the panel's frames, and the preference. */
export interface OverlayMotionOptions {
  /** The primitive's open state: the machine follows it, so a request the host refuses never moves the box. */
  readonly open: Accessor<boolean>;
  /** Structural, read once: off, the box lands in one microtask and no animation starts. */
  readonly animated: boolean;
  /** The panel's frames: the dialog fades and lifts, the drawer slides off its own edge. */
  readonly frame: OverlayFrame;
  /** The motion preference; left out, `prefers-reduced-motion: reduce` is read once. */
  readonly reducedMotion?: boolean | undefined;
  /** Every animation the host starts, once, after `animate()`: a test pauses it and steps the timeline. */
  readonly onAnimate?: ((animation: Animation) => void) | undefined;
}

/** The machine as the layer reads it: a phase, a presence, and the panel the effects run on. */
export interface OverlayMotion {
  readonly machine: OverlayMotionMachine;
  readonly store: MachineStore<
    OverlayMotionContext,
    OverlayMotionPhase,
    OverlayMotionEvent
  >;
  /** The box, from the committed store: one field, and a reader of it does not re-run for the others. */
  readonly phase: Accessor<OverlayMotionPhase>;
  /** The layer is mounted: the box is not closed, or the primitive is open and the box has yet to follow it. */
  readonly visible: Accessor<boolean>;
  readonly attach: (element: HTMLElement | undefined) => void;
}

interface LiveAnimation {
  readonly handle: EffectHandle;
  readonly animation: Animation;
  readonly from: number;
  readonly to: number;
  readonly duration: number;
}

const prefersReducedMotion = (): boolean =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * Run the box for one layer. Call it in a component body: the store and its projections belong to the component, and
 * disposing it unsubscribes from the machine and settles it.
 */
export const createOverlayMotion = (options: OverlayMotionOptions): OverlayMotion => {
  const animated = options.animated;
  const machine: OverlayMotionMachine = createMachine(
    overlayMotionDefinition(
      untrack(() => options.reducedMotion) ?? prefersReducedMotion(),
      untrack(() => options.open()) ? "open" : "closed",
    ),
  );
  const store = createMachineStore(machine);
  const view = store.projection(
    (draft, state) => {
      draft.visible = state.phase !== "closed";
    },
    { visible: false },
  );

  let panel: HTMLElement | undefined;
  /** The live animation, or `undefined` at rest (and for the instant between a cancel and its replacement). */
  let live: LiveAnimation | undefined;
  /** Where a cancelled animation stopped: the reversal's start. */
  let carried: number | undefined;

  const fractionOf = (running: LiveAnimation): number => {
    const time = Number(running.animation.currentTime ?? 0);
    return running.duration === 0 ? 0 : Math.min(1, Math.max(0, time / running.duration));
  };

  const offEffect = machine.onEffect((handle) => {
    const to = handle.spec.to === "open" ? 1 : 0;
    // a reversal keeps the box where it was; a start begins at the end the box is already at
    const from = carried ?? (to === 1 ? 0 : 1);
    carried = undefined;
    const element = panel;
    if (element === undefined || !animated) {
      // no motion asked for, or nothing mounted to animate: the box lands at once, and the finish is a microtask so a
      // transition is still one delivery
      queueMicrotask(() => machine.send({ type: "finish", id: handle.id }));
      return;
    }
    const distance = Math.abs(to - from);
    // the box moves at a constant rate, so the duration is what is left to travel; `fill: none` because the panel's own
    // state styling is the animation's end in either direction
    const duration = OVERLAY_MOTION_DURATION * Math.max(distance, 0.001);
    const animation = element.animate([options.frame(from), options.frame(to)], {
      duration,
      easing: "linear",
      fill: "none",
    });
    // the ends, for a test that steps the timeline; the id is the least visible place to keep them
    animation.id = `${from}:${to}`;
    live = { handle, animation, from, to, duration };
    options.onAnimate?.(animation);
    const done = (): void => {
      if (live?.handle.id === handle.id) {
        live = undefined;
      }
      animation.cancel();
      // a completion, and a cancelled animation's own late one: the machine drops the latter by its id
      machine.send({ type: "finish", id: handle.id });
    };
    animation.finished.then(done, done);
  });

  const offCancel = machine.onCancel((handle) => {
    if (live?.handle.id !== handle.id) {
      return;
    }
    const cancelled = live;
    // read before `cancel()`: a cancelled animation's `currentTime` is null
    carried = fractionOf(cancelled);
    live = undefined;
    cancelled.animation.cancel();
  });

  // The machine follows the primitive. The delivery is a microtask because an effect runs in an owned scope, where the
  // store refuses a write; the layer's presence does not wait for it — it reads `open()` too, so the panel is in the
  // DOM before the primitive moves the focus into it.
  createEffect(
    () => options.open(),
    (open) => {
      queueMicrotask(() => {
        if (open !== machine.getState().context.logical) {
          machine.send({ type: open ? "open" : "close" });
        }
      });
    },
  );

  createEffect(
    () => options.reducedMotion,
    (reduced) => {
      if (reduced === undefined) {
        return;
      }
      queueMicrotask(() => {
        if (reduced !== machine.getState().context.reduced) {
          machine.send({ type: "motion", reduced });
        }
      });
    },
  );

  onCleanup(() => {
    offEffect();
    offCancel();
    machine.destroy();
  });

  // The box as the layer shows it (`data-state`). The machine follows `open()` on the next microtask, so for the flush
  // that mounts the panel — before the primitive can move the focus into it — the box is where it is heading: `entering`,
  // or `open` at once when the preference skips the transition. A mounted layer is never shown at the `closed` end.
  const shown = (): OverlayMotionPhase => {
    const phase = store.state.phase;
    if (phase !== "closed" || !options.open()) {
      return phase;
    }
    return machine.getState().context.reduced ? "open" : "entering";
  };

  return {
    machine,
    store,
    phase: shown,
    visible: () => options.open() || view.visible,
    attach: (element) => {
      panel = element;
    },
  };
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };
